import React, { useEffect, useState } from 'react';
import { Building, Resources } from '../../types/game';
import '../../styles/components/BuildingInfo.css';

interface BuildingInfoProps {
  building: Building;
  onClose: () => void;
  playerResources: Resources;
}

const BuildingInfo: React.FC<BuildingInfoProps> = ({ building, onClose, playerResources }) => {
  // Estado local para tener los datos más actualizados del edificio
  const [buildingData, setBuildingData] = useState<Building>(building);
  
  // Actualizar el estado local cuando cambie el prop building
  useEffect(() => {
    setBuildingData(building);
  }, [building]);

  const getStatusText = () => {
    if (!buildingData.built) return "No construido";
    return "Construido";
  };

  return (
    <div className="building-info">
      <div className="building-info-header">
        <h3>{buildingData.name}</h3>
        <button onClick={onClose} className="close-button">×</button>
      </div>
      <div className="building-info-content">
        <p><strong>Estado:</strong> {getStatusText()}</p>
        
        {!buildingData.built && (
          <div className="building-cost">
            <h4>Costo de construcción:</h4>
            <ul>
              <li className="cost-item">
                <span className="resource-icon gold-icon">🪙</span>
                <span>{buildingData.cost?.gold || 0} oro</span>
              </li>
              <li className="cost-item">
                <span className="resource-icon wood-icon">🪵</span>
                <span>{buildingData.cost?.wood || 0} madera</span>
              </li>
              <li className="cost-item">
                <span className="resource-icon stone-icon">🪨</span>
                <span>{buildingData.cost?.stone || 0} piedra</span>
              </li>
            </ul>
          </div>
        )}
        
        {buildingData.built && buildingData.can_recruit && (
          <div className="building-allows-recruitment">
            <h4>Permite reclutar unidades</h4>
            {buildingData.available_creatures && buildingData.available_creatures.length > 0 ? (
              <div className="available-units">
                <h4>Unidades disponibles:</h4>
                <ul>
                  {buildingData.available_creatures.map((creature, index) => (
                    <li key={index}>
                      {creature.type}: <strong>{creature.count} disponibles</strong>
                      {creature.unit_cost && (
                        <div className="unit-cost">
                          Costo por unidad: 
                          {Object.entries(creature.unit_cost).map(([resource, cost]) => 
                            cost > 0 ? (
                              <span key={resource} className="cost-item">
                                <span className={`resource-icon ${resource}-icon`}>
                                  {resource === 'gold' ? '🪙' : resource === 'wood' ? '🪵' : '🪨'}
                                </span>
                                {cost}
                              </span>
                            ) : null
                          )}
                        </div>
                      )}
                    </li>
                  ))}
                </ul>
              </div>
            ) : (
              <p>No hay unidades disponibles para reclutar.</p>
            )}
          </div>
        )}
        
        {buildingData.requirements && buildingData.requirements.length > 0 && (
          <div className="building-requirements">
            <h4>Requisitos:</h4>
            <ul>
              {buildingData.requirements.map((req, index) => (
                <li key={index}>{req}</li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
};

export default BuildingInfo;
